const projects=[
{slug:'almaymaar',name:'Almaymaar',line:'I changed how a company thinks about its brand.',summary:'Replaced reactive posting with a named content system — corporate positioning end to end.',image:'/assets/almaymaar-1.png',blocks:[['Changing the story real estate tells.','Pakistani real estate had become predictable. Developers talked about projects, prices, amenities and promises. Every brand sounded like it was selling the same dream. Almaymaar needed a different belief system. So we stopped treating content as a stream of promotional posts and built an editorial system around why this way, from the site, and people & places.'],['Why This Way','We challenged the way Pakistani developers sell. Instead of asking people to believe another property promise, we built a point of view around why Almaymaar builds the way it does. Architecture. Decisions. Materials. Intent. The thinking behind the development became part of the brand.\n\nThe objective wasn’t to sell harder. It was to build belief.'],['From the Site','Construction stopped being something to hide until the finished product. We took people onto the site, showed the progress, the materials, the decisions and the people behind the build. The promise became visible.'],['People & Places','Beyond the buildings, we explored the people, places, culture and details surrounding them. The brand became a place you could experience before you bought into it.'],['The result','8,000+ organic followers in 10 months. An audience built around a real-estate brand without turning the feed into a property catalogue.']],gallery:['/assets/almaymaar-2.png','/assets/almaymaar-3.png']},
{slug:'harsukh',name:'The Harsukh',line:'I built belief, and it moved the inventory.',summary:'Helped take a flagship from 15 to 68 units sold in one year.',image:'/assets/harsukh-1.jpeg',blocks:[['A place without an identity','Harsukh was a beautiful place without much of an identity around it, so I wanted to build the brand around the people and the reality behind making it.'],['Show what nobody else was showing','Instead of hiding the construction, we took people to the site, introduced the labourers and showed the progress, something rarely seen in Pakistani real estate. We told the story of what it actually takes to build in the extreme weather of Galiyat.'],['Then we built the world around it','I shaped the interiors, developed AI-led visual storytelling for the campaign, built presenter-led lead-generation content and helped give Harsukh a visual and narrative language of its own.'],['And it moved','The brand grew to 7,000 organic followers in a single month, while the flagship had sold 15 units when I joined and 68 during my first year. The story, the place and the business finally started moving together.']],gallery:['/assets/harsukh-2.jpeg']},
{slug:'downtownlahore',name:'Downtown Lahore',line:'I sell a place by selling the idea of it.',summary:'A TVC made to turn a destination into a national conversation.',blocks:[['The idea of a destination','Downtown Lahore needed to feel larger than a development. The work framed it as a destination with its own energy, rhythm and cultural pull.'],['A national conversation','The campaign used film and a clear central thought to make the place memorable before audiences ever arrived. The goal was to sell the feeling of being there, not simply list what would be built.'],['My role','Creative direction, narrative development and campaign storytelling.']]},
{slug:'crafeupstairs',name:'Crafé Upstairs',line:'I turned a space into a story people bought.',summary:'A reveal that turned a hidden coffee space into something people wanted to discover.',blocks:[['A space that needed a reason to gather','Crafé was already a coffee space in Cantt, Lahore, but its upstairs area was largely undiscovered. The challenge was to introduce it without making the launch feel like another restaurant announcement.'],['We started with the thought behind Crafé','I created a storytelling film around the founding thought of Crafé, using that idea as the starting point for the reveal. I also developed the supporting content and launch material around the same narrative.'],['Then we let people discover it','The film became the centrepiece of the reveal. The result was simple: people showed up, the upstairs became a place to gather, and the tables filled.']]},
{slug:'kiapakistan',name:'KIA Pakistan',line:"I wrote a ‘movement’ that inspired.",summary:'A launch film built around two teams, two SUVs, and a race where nobody could lose.',blocks:[['A race where nobody could lose','KIA was launching the all-new Sorento and Sportage. Put two cars in a race and someone has to lose. We needed the excitement of a real competition without making either SUV feel like the losing product.'],['So we made the difference the story','I wrote the concept around two teams, six creators and two SUVs racing from Islamabad towards Nathiagali. The Sportage brought energy and agility, while the Sorento took a more effortless approach. The cars experienced their features through the creators and the way each team chose to travel.'],['And then Junejo stopped the race','Midway through the journey, Irfan Junejo spotted the perfect golden-hour light. The team wanted to keep moving, but he stopped anyway. “Race ruk sakti hai... golden hour aur content paglu nahi.” The Sorento arrived first by only a few seconds. Nobody really lost.'],['My role','Ad concept, narrative structure and dialogue. The concept was handed to the agency for production and execution.']]},
{slug:'imarat',name:'IMARAT',line:'I turn a dry mechanic into a story.',summary:'Making large, complicated places understandable and worth caring about.',blocks:[['I learned to make big places understandable','IMARAT was where I began working at the intersection of real estate, marketing and storytelling. Projects like Grand Bazaar and Mall of IMARAT were enormous ideas that needed to be understood quickly by people who might eventually invest in them.'],['We turned the project into a story','For Grand Bazaar, I worked on the concept and messaging and presented the film myself. For Mall of IMARAT, I developed explainer content around its location, architectural scale and commercial proposition. The videos became sales tools as much as marketing pieces.'],['My role','Creative & Brand Manager — concept and messaging, brand storytelling, project marketing, on-camera presentation and investor communication.'],['This is the beginning of the story','Before I was building brand systems, I was learning how to take something massive, complicated and commercial and find the story inside it.']]},
{slug:'chakor',name:'Chakor Ventures',line:'I found my craft in the making of a city.',summary:'Stories built around places made to change the skyline.',blocks:[["I made the brand’s promise visible",'Chakor Ventures had a simple idea at the heart of its brand: achieving heights. I wanted to turn that line from something a brand says into something the audience could actually see.'],['So I climbed to the top of it','For Citadel 7, I developed a short-form reel around one simple hook: get on the crane. I climbed high above the construction site and delivered the brand story from a perspective people would not normally see. The crane became the idea.'],['Then I made the complicated stuff watchable','For the 60–40 campaign, I created a conversational format where I appeared as both interviewer and guest, unpacking the payment structure as content rather than a sales pitch.'],['My role','Creative Strategist — creative concept, campaign ideas, brand messaging, content strategy, on-camera presentation and digital campaigns.']]}
];
const app=document.querySelector('#app');
const esc=s=>s.replace(/[&<>"']/g,m=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#039;'}[m]));
function home(){return `<section class="hero"><div class="hero-copy"><span class="intro">Hi, I’m Wasib Imdad</span><h1 class="display">Creative<em>Maker</em>Storyteller</h1><div class="hero-bottom"><span class="eyebrow">What I do</span><div><p>I find the story in an idea, then build the world around it. Across brands, campaigns, places and films, I turn what needs to be said into something people can see, feel, and remember.</p><a class="cta" href="/work/" data-link>View work</a></div></div></div><div class="hero-media"><img src="/assets/hero.png" alt="Wasib Imdad seated in a studio portrait"><span class="media-label">Creative Director · Lahore</span></div></section><section class="statement"><span class="eyebrow">I create</span><h2>Brands. Places.<br><em>Stories.</em></h2></section><a class="film" href="/work/" data-link aria-label="Explore Wasib’s selected work"><img src="/assets/polaroids.png" alt="A selection of Wasib’s creative work"><span class="play">View</span></a>`}
function work(){const rows=[
['almaymaar','I changed how a company thinks about its brand','Replaced reactive posting with a named content system — corporate positioning end to end.'],
['harsukh','I built belief & it moved the inventory.','Helped take a flagship from a mere 14 to 65 units sold – in a year!'],
['downtownlahore','I sell a place by selling the idea of it.','A TVC made to turn a destination into a national conversation.'],
['crafeupstairs','I turned a space into a story people bought.','A reveal that turned a hidden coffee space into something people wanted to discover.'],
['kiapakistan',"I wrote a 'Movement' that inspired.",'A launch film for KIA Pakistan – a race between the Sorento and Sportage.'],
['imarat','I turn a dry mechanic into a story.','Invented a format to make a payment structure something people could actually grasp.'],
['chakor','I found my craft in the making of a city.','Stories built around places made to change the skyline.']
];return `<section class="portfolio-panel"><header class="portfolio-intro"><h1>Portfolio</h1><p>A selection of work spanning products, brands, content and creative direction.</p></header><div class="portfolio-rows">${rows.map(r=>`<a class="portfolio-row" href="/${r[0]}/" data-link><h2>${r[1]}</h2><p>${r[2]}</p></a>`).join('')}</div></section>`}
function project(p){const next=projects[(projects.indexOf(p)+1)%projects.length];return `<section class="project-hero"><div class="project-title"><span class="eyebrow">Selected work</span><h1>${p.name}</h1><p>${p.line}</p></div>${p.image?`<div class="project-image"><img src="${p.image}" alt="${esc(p.name)} project image"></div>`:`<div class="project-image placeholder">${p.name}</div>`}</section><article class="case-body">${p.blocks.map(b=>`<section class="case-block"><h2>${b[0]}</h2><p>${b[1]}</p></section>`).join('')}${p.gallery?`<div class="gallery">${p.gallery.map((im,i)=>`<img src="${im}" alt="${esc(p.name)} project detail ${i+1}">`).join('')}</div>`:''}</article><a class="next" href="/${next.slug}/" data-link><span>Next project</span><span>${next.name} ↗</span></a>`}
function about(){return `<section class="about-grid"><div class="about-image"><img src="/assets/about.png" alt="Portrait of Wasib Imdad"></div><article class="about-copy"><span class="eyebrow">About</span><h1>I just want to <em>make things.</em></h1><p>Hi, I’m Wasib. I’m a Creative Director, but I’ve never been particularly interested in staying inside the boundaries of a job title.</p><p>I like ideas. More specifically, I like what happens when an idea leaves someone’s head and becomes something real.</p><p>A brand people recognise. A film people remember. A place people want to visit. A product people want to hold. A story that makes something ordinary feel worth paying attention to.</p><p>I enjoy the making as much as the thinking. I want to shape the frame, question the type, change the edit, rewrite the line, move the image and keep going until the thing feels right.</p><p class="question">How do we make someone care?</p><p>Sometimes the answer is a brand. Sometimes it’s a campaign. Sometimes it’s a thirty-second film. Sometimes it’s just one sentence in exactly the right place.</p><p>I don’t think good creative work needs to shout to be powerful. It just needs to make you stop for a second.</p><p>That’s what I’m trying to make. Things that are useful, thoughtful and carefully made. Things with a point of view. Things people can feel.</p></article></section>`}
function contact(){return `<section class="contact-page"><span class="eyebrow">Have a project in mind?</span><div><h1>Let’s make<br>something<br>worth feeling.</h1><a class="email" href="mailto:wasib@wasib.co">wasib@wasib.co ↗</a><div class="contact-links"><a href="https://instagram.com/wasib25">Instagram</a><a href="https://linkedin.com">LinkedIn</a></div></div></section>`}
function render(){const path=location.pathname.replace(/^\/+|\/+$/g,'');let html;if(!path)html=home();else if(path==='work')html=work();else if(path==='about')html=about();else if(path==='contact')html=contact();else{const p=projects.find(x=>x.slug===path);html=p?project(p):work()}document.body.classList.toggle('is-work-page',path==='work');app.innerHTML=html;document.title=path?`${path==='work'?'Work':path==='about'?'About':path==='contact'?'Contact':projects.find(x=>x.slug===path)?.name||'Work'} — Wasib Imdad`:'Wasib Imdad — Creative Director';document.querySelectorAll('[data-link]').forEach(a=>a.onclick=e=>{e.preventDefault();history.pushState({},'',a.href);render();scrollTo(0,0)});document.querySelector('#year').textContent=new Date().getFullYear()}
document.querySelector('.menu').onclick=e=>{const n=document.querySelector('nav');n.classList.toggle('open');e.currentTarget.setAttribute('aria-expanded',n.classList.contains('open'))};addEventListener('popstate',render);render();
